    if X.shape[1] != W1.shape[0]:
        raise ValueError("X und W1 passen nicht zusammen")
    if W1.shape[1] != b1.shape[0]:
        raise ValueError("W1 und b1 passen nicht zusammen")
    if W1.shape[1] != W2.shape[0]:
